INSERT INTO Prospect (AgencyID, SK_RecordDateID, SK_UpdateDateID, BatchID, IsCustomer, LastName, FirstName, MiddleInitial, Gender, AddressLine1, AddressLine2, PostalCode, City, State, Country, Phone, Income, numberCars, numberChildren, MaritalStatus, Age, CreditRating, OwnOrRentFlag, Employer, numberCreditCards, NetWorth, MarketingNameplate) SELECT CAST(P.AgencyID AS TEXT) AS AgencyID, CAST((SELECT DimDate.SK_DateID FROM DimDate WHERE DimDate.DateValue = (SELECT Source.BatchDate.BatchDate FROM Source.BatchDate)) AS INT) AS SK_RecordDateID, CAST((SELECT d.SK_DateID FROM DimDate AS d WHERE d.DateValue = (SELECT b.BatchDate FROM Source.BatchDate AS b)) AS INT) AS SK_UpdateDateID, CAST(1 AS DECIMAL(5, 0)) AS BatchID, CAST(NULL AS BOOLEAN) AS IsCustomer, CAST(UPPER(TRIM(P.LastName)) AS TEXT) AS LastName, CAST(ARRAY_TO_STRING(CASE WHEN REGEXP_MATCHES(LEFT(TRIM(P.FirstName), 1), '[' || (' 	
' || CHR(11) || '!"#$%&''()*+,\\\-./:;<=>?@\\\[\\\]\^_`{|}~') || ']') THEN LIST_TRANSFORM(REGEXP_EXTRACT_ALL(TRIM(P.FirstName), '([' || (' 	
' || CHR(11) || '!"#$%&''()*+,\\\-./:;<=>?@\\\[\\\]\^_`{|}~') || ']+|[^' || (' 	
' || CHR(11) || '!"#$%&''()*+,\\\-./:;<=>?@\\\[\\\]\^_`{|}~') || ']+)'), LAMBDA seg, idx : CASE WHEN idx % 2 = 0 THEN UPPER(LEFT(seg, 1)) || LOWER(SUBSTRING(seg, 2)) ELSE seg END) ELSE LIST_TRANSFORM(REGEXP_EXTRACT_ALL(TRIM(P.FirstName), '([' || (' 	
' || CHR(11) || '!"#$%&''()*+,\\\-./:;<=>?@\\\[\\\]\^_`{|}~') || ']+|[^' || (' 	
' || CHR(11) || '!"#$%&''()*+,\\\-./:;<=>?@\\\[\\\]\^_`{|}~') || ']+)'), LAMBDA seg, idx : CASE WHEN idx % 2 = 1 THEN UPPER(LEFT(seg, 1)) || LOWER(SUBSTRING(seg, 2)) ELSE seg END) END, '') AS TEXT) AS FirstName, CAST(P.MiddleInitial AS TEXT) AS MiddleInitial, CAST(UPPER(P.Gender) AS TEXT) AS Gender, CAST(P.AddressLine1 AS TEXT) AS AddressLine1, CAST(P.AddressLine2 AS TEXT) AS AddressLine2, CAST(P.PostalCode AS TEXT) AS PostalCode, CAST(P.City AS TEXT) AS City, CAST(P.State AS TEXT) AS State, CAST(P.Country AS TEXT) AS Country, CAST(P.Phone AS TEXT) AS Phone, CAST(P.Income AS DECIMAL(9, 0)) AS Income, CAST(P.NumberCars AS DECIMAL(2)) AS numberCars, CAST(P.NumberChildren AS DECIMAL(2, 0)) AS numberChildren, CAST(P.MaritalStatus AS TEXT) AS MaritalStatus, CAST(P.Age AS DECIMAL(3, 0)) AS Age, CAST(P.CreditRating AS DECIMAL(4, 0)) AS CreditRating, CAST(P.OwnOrRentFlag AS TEXT) AS OwnOrRentFlag, CAST(P.Employer AS TEXT) AS Employer, CAST(P.NumberCreditCards AS DECIMAL(2)) AS numberCreditCards, CAST(P.NetWorth AS DECIMAL(12)) AS NetWorth, CAST(COALESCE(CAST(P.Age AS TEXT), '') || '|' || COALESCE(CAST(P.NetWorth AS TEXT), '') || '|' || COALESCE(CAST(P.Income AS TEXT), '') || '|' || COALESCE(CAST(P.NumberChildren AS TEXT), '') || '|' || COALESCE(CAST(P.NumberCreditCards AS TEXT), '') || '|' || COALESCE(CAST(P.NumberCars AS TEXT), '') || '|' || COALESCE(CAST(P.CreditRating AS TEXT), '') AS TEXT) AS MarketingNameplate FROM Source.Prospect AS P;
